#!/bin/bash
# AI DISCLAIMER: All of the text in this file was generated by AI.
# G018 box3900x replays (control box: restores and starts runs on box3900x, then waits; no build or benchmark here).
# Waits for BUILD_DOT9_DONE ok with the new tests, the ringct/tx_verification_utils suites and both crate suites passing.
# Then per run: restore stressnet_h3103300c into box3900x's working DB, start the run script detached, wait for
# BPP_RUN_DONE. 11 cores (bpp_run_all.sh): B N P P N B; 4 cores (bpp_run.sh): B N N B. Stops at the first failure.
# Marker CHAIN_DOT9H_DONE <ok|FAIL>.
set -u
G=$CTRL/dot9; L=$G/chain_dot9h.log
A=$HOME/work/research-artifacts; R=$A/bpp/runs; BL=$HOME/work/g016/build_dot9.log
B=$A/dot9/monerod-dot8-e7bae3ecf; N=$A/dot9/monerod-dot9-6bb32ea00; P=$A/bpp/kit/monerod-P
log() { echo "$(date -u +%FT%TZ) $*" >> $L; }
fail() { log "$*"; log "CHAIN_DOT9H_DONE FAIL"; exit 1; }
log "chain start"
until ssh -n box3900x "grep -q BUILD_DOT9_DONE $BL"; do sleep 60; done
ssh -n box3900x "grep -q 'BUILD_DOT9_DONE ok' $BL" || fail "build not ok"
ssh -n box3900x "grep -A12 '== new tests' $BL | grep -q 'PASSED' && ! grep -A12 '== new tests' $BL | grep -q 'FAILED'" || fail "new tests not passed"
ssh -n box3900x "grep -A3 '== ringct and tx_verification_utils' $BL | grep -q 'rc=0'" || fail "ringct/tx suites not rc=0"
# the crate tests run on copies by crate_tests_dot9.sh (the build script's in-tree cargo run is offline-vendored and cannot)
CM=$HOME/work/g016/crate_dot9.marker
until ssh -n box3900x "grep -q CRATE_DOT9_DONE $CM"; do sleep 60; done
EM=$HOME/work/g016/extra_dot9.marker
until ssh -n box3900x "grep -q EXTRA_DOT9_DONE $EM"; do sleep 60; done
ssh -n box3900x "grep -q 'gbp --features tests rc=0' $CM && grep -q 'fcmps rc=0' $CM && grep -q 'ca rc=0' $EM && grep -q 'notify rc=0' $EM" || fail "crate tests or notify not rc=0"
log "build and tests ok"
ssh -n box3900x "ls -la $B $N $P" >> $L || fail "a binary is missing"
run() {	# <script> <name> <binary>
  local sc=$1 name=$2 bin=$3
  ssh -n box3900x "pgrep -u $USER -x monerod" > /dev/null && fail "a monerod runs on box3900x"
  ssh -n box3900x "pgrep -x shadow" > /dev/null && fail "shadow runs on box3900x"
  ~/snapshots/snapctl.sh restore box3900x stressnet_h3103300c >> $L 2>&1 || fail "restore failed before $name"
  sleep 60   # let the restore's writeback settle
  log "start $name ($sc)"
  ssh -n box3900x "cd ~/work/g016 && (END=3103500 setsid nohup bash $sc $name $bin > $name.out 2>&1 < /dev/null &)"
  until ssh -n box3900x "grep -q BPP_RUN_DONE $R/$name/run.log 2>/dev/null"; do sleep 30; done
  ssh -n box3900x "tail -4 $R/$name/run.log" >> $L
  ssh -n box3900x "grep -q 'BPP_RUN_DONE end' $R/$name/run.log && grep -q HASH_OK $R/$name/run.log" || fail "$name did not end ok"
}
run bpp_run_all.sh d9x1_B $B
run bpp_run_all.sh d9x1_N $N
run bpp_run_all.sh d9x1_P $P
run bpp_run_all.sh d9x2_P $P
run bpp_run_all.sh d9x2_N $N
run bpp_run_all.sh d9x2_B $B
ssh -n box3900x "python3 -I ~/work/g016/dot9_ab.py $R d9x1_B d9x1_N d9x1_P d9x2_P d9x2_N d9x2_B" >> $L 2>&1
run bpp_run.sh d9f1_B $B
run bpp_run.sh d9f1_N $N
run bpp_run.sh d9f2_N $N
run bpp_run.sh d9f2_B $B
ssh -n box3900x "python3 -I ~/work/g016/dot9_ab.py $R d9f1_B d9f1_N d9f2_N d9f2_B" >> $L 2>&1
log "CHAIN_DOT9H_DONE ok"
